Contohnya:
DECLARE @Counter INT;
SET @Counter = 1;
WHILE ( @Counter <= 10 )
BEGIN
  PRINT 'The counter value is = ' + CONVERT(VARCHAR,@Counter);
  SET @Counter = @Counter + 1;
END

DECLARE @StudentMarks INT = 91;
IF @StudentMarks >= 80
   PRINT 'Passed, Congratulations!!';
ELSE
   PRINT 'Failed, Try again ';

